INSERT INTO expense_submission_control(tenant_id,report_id,application_id,employee_id,round_no,
submitted_financial_version,precheck_id,paper_required,receipt_received,version,input_json,state_json,submitted_at)
SELECT tenant_id,report_id,application_id,employee_id,#{roundNo},financial_version+1,id,#{paperReceiptRequired},FALSE,1,#{stateJson},#{stateJson2},#{submittedAt}
FROM expense_precheck_job WHERE tenant_id=#{tenantId} AND report_id=#{reportId} AND application_id=#{applicationId} AND employee_id=#{employeeId} AND id=#{precheckId}
AND status='READY' AND financial_version=#{submittedFinancialVersion}
